// 서브 식별 계약. 문서와 태스크의 정형화된 세부항목이 부모를 다는 형태다.
//
// 이 파일이 존재하는 이유는 편의가 아니라 경계다. 값 목록은 src/vocabulary.js가
// 갖지만 그 파일은 "필드가 가질 수 있는 값"만 담고 필드의 이름은 담지 않기로
// 되어 있다. 부모와 종류와 일련이라는 세 자리는 필드의 이름이므로 여기 온다 —
// types/workflow.d.ts가 판정 계약에, types/assignment.d.ts가 검수 판정에 같은
// 일을 하고 있다.
//
// workflow.d.ts에 얹지 않는 이유는 서브가 워크플로의 개념이 아니기 때문이다.
// 서브는 진행 축을 갖지 않고 상태도 전환도 없다. 한 파일에 두면 판정 계약을 읽는
// 사람이 서브의 전환을 찾게 되고, 없는 것을 찾는 일은 대개 만들어 넣는 것으로 끝난다.
//
// 이것이 갈래보다 먼저 커밋되는 이유도 workflow.d.ts와 같다. 서브를 문서에 심는
// 갈래와 이관에 얹는 갈래와 진단 둘을 걷어내는 갈래는 담당 파일이 겹치지 않지만
// 이 계약을 공유한다. 계약이 합의로 남으면 한쪽이 조용히 넓힌 것이 병합에서야
// 드러난다.

/** src/vocabulary.js의 SUB_KINDS. 세 자리 중 코드가 소유하는 것은 이것뿐이다. */
export type SubKind = 'FN' | 'SC' | 'AC';

/**
 * 서브 하나의 신원. 부모와 종류와 일련이며 닫힌 것은 가운데뿐이다.
 *
 * 부모를 값으로 들고 있는 것이 이 레코드의 전부라고 해도 된다. 지금 기능 ID는
 * 부모가 없어서 전역 이름공간에 살고, 그래서 중복을 막는 진단과 원천 없는 참조를
 * 막는 진단이 둘 다 전역으로 서 있다. 부모가 들어오면 그 둘은 막을 것이 없어진다 —
 * 유일성의 범위가 부모 안으로 줄어들기 때문이고, 시나리오가 이미 그렇게 산다.
 *
 * 전역 유일을 요구하지 않는다. 요구하면 부모를 단 뜻이 사라지고, 프로젝트가 커질수록
 * 사람이 짓는 이름이 다시 길어진다.
 */
export interface SubIdentity {
  /**
   * 부모의 식별자. 문서 또는 태스크이며 프로젝트가 정의한 값이다.
   * 형태를 여기서 못박지 않는다 — 못박으면 사용자가 정의한 것이 다시 코드가 된다.
   */
  parent: string;
  kind: SubKind;
  /**
   * 부모 안에서의 일련. 값은 데이터이고 표기만 정해져 있다 —
   * src/vocabulary.js의 ID_PATTERNS.sub가 그 자릿수를 갖는다.
   */
  serial: string;
  /**
   * 정형화되지 않은 항목에 임시로 붙은 서브인지. 임시인 것은 advisory 진단이
   * 따라붙되 막지는 않는다.
   *
   * 이 칸이 필요한 이유는 이관에 있다. 지금 서브를 갖지 않은 항목이 대부분이고,
   * 그것들을 한 번에 정형화하지 못한 채로 부모만 달면 "사람이 정한 서브"와
   * "도구가 채운 서브"가 구분되지 않는다. 구분되지 않으면 임시가 영구가 되고,
   * 그 사실은 아무 신호도 내지 않는다.
   */
  provisional: boolean;
}

/**
 * 문서 안에서의 표기 — FN-001. 부모가 자명하므로 붙이지 않는다.
 *
 * 문자열인 것은 이 값이 사람이 문서에 적는 글자이기 때문이다. 구조로 들어오는
 * 자리는 SubIdentity이고, 이쪽은 그것을 적고 읽는 표기다.
 */
export type LocalSubRef = string;

/**
 * 문서 밖에서의 표기 — REQ-033#FN-001. 부모와 서브를 SUB_ID_SEPARATOR가 잇는다.
 *
 * 시나리오가 이미 쓰는 규칙(TST-017#S-03)을 넓힌 것이다. 새 표기를 짓지 않는 이유는
 * 이미 그 표기로 적힌 참조가 있고, 둘을 두면 같은 것을 가리키는 글자가 둘이 되기
 * 때문이다.
 */
export type QualifiedSubRef = string;
